alter table public.programming_exercises add column if not exists daily_challenge_day smallint, add column if not exists daily_challenge_difficulty text;
create unique index if not exists programming_exercises_daily_challenge_unique on public.programming_exercises(daily_challenge_day,daily_challenge_difficulty) where daily_challenge_day is not null;
with seed as (select * from jsonb_to_recordset('[{"day":1,"diff":"beginner","title":"مجموع رقمين","instructions":"اقرأ رقمين واطبع مجموعهما.","starter":"a,b=map(int,input().split())","hint":"استخدم split وتحويل int.","solution":"a,b=map(int,input().split());print(a+b)","tests":[{"label":"اختبار 1","stdin":"3 5\n","expected_output":"8"},{"label":"اختبار 2","stdin":"-4 9\n","expected_output":"5"}]},{"day":1,"diff":"intermediate","title":"عدّ الحروف المتحركة","instructions":"احسب a,e,i,o,u في كلمة دون حساسية حالة الأحرف.","starter":"s=input().strip()","hint":"حوّل إلى lowercase وافحص كل حرف.","solution":"s=input().lower();print(sum(c in \"aeiou\" for c in s))","tests":[{"label":"اختبار 1","stdin":"Education\n","expected_output":"5"},{"label":"اختبار 2","stdin":"rhythm\n","expected_output":"0"}]},{"day":1,"diff":"advanced","title":"أطول كلمة","instructions":"اطبع أطول كلمة؛ وعند التعادل اختر الأولى.","starter":"w=input().split()","hint":"استخدم max مع key=len.","solution":"w=input().split();print(max(w,key=len) if w else \"\")","tests":[{"label":"اختبار 1","stdin":"code makes ideas real\n","expected_output":"ideas"},{"label":"اختبار 2","stdin":"red sky sun\n","expected_output":"red"}]},{"day":2,"diff":"beginner","title":"مربع العدد","instructions":"اطبع مربع عدد صحيح.","starter":"n=int(input())","hint":"اضرب العدد في نفسه.","solution":"n=int(input());print(n*n)","tests":[{"label":"اختبار 1","stdin":"6\n","expected_output":"36"},{"label":"اختبار 2","stdin":"-3\n","expected_output":"9"}]},{"day":2,"diff":"intermediate","title":"مجموع الزوجي","instructions":"اطبع مجموع الأعداد الزوجية.","starter":"a=list(map(int,input().split()))","hint":"اختبر n%2==0.","solution":"a=list(map(int,input().split()));print(sum(x for x in a if x%2==0))","tests":[{"label":"اختبار 1","stdin":"1 2 3 4\n","expected_output":"6"},{"label":"اختبار 2","stdin":"1 3 5\n","expected_output":"0"}]},{"day":2,"diff":"advanced","title":"ضغط النص","instructions":"حوّل aaabb إلى a3b2 بعد عدّ التكرارات المتجاورة.","starter":"s=input().strip()","hint":"عدّ الحرف حتى يتغير.","solution":"s=input().strip();o=[]\nif s:\n c=1\n for i in range(1,len(s)):\n  if s[i]==s[i-1]:c+=1\n  else:o.append(s[i-1]+str(c));c=1\n o.append(s[-1]+str(c))\nprint(\"\".join(o))","tests":[{"label":"اختبار 1","stdin":"aaabbc\n","expected_output":"a3b2c1"},{"label":"اختبار 2","stdin":"abcd\n","expected_output":"a1b1c1d1"}]},{"day":3,"diff":"beginner","title":"تحويل الدقائق","instructions":"اطبع الساعات والدقائق المتبقية.","starter":"m=int(input())","hint":"استخدم // و%.","solution":"m=int(input());print(m//60,m%60)","tests":[{"label":"اختبار 1","stdin":"90\n","expected_output":"1 30"},{"label":"اختبار 2","stdin":"45\n","expected_output":"0 45"}]},{"day":3,"diff":"intermediate","title":"كلمة متناظرة","instructions":"تحقق هل الكلمة تقرأ بنفس الشكل من الاتجاهين.","starter":"s=input().strip()","hint":"قارنها بمعكوسها.","solution":"s=input().strip();print(s==s[::-1])","tests":[{"label":"اختبار 1","stdin":"level\n","expected_output":"True"},{"label":"اختبار 2","stdin":"python\n","expected_output":"False"}]},{"day":3,"diff":"advanced","title":"الأكثر تكرارًا","instructions":"اطبع الأكثر تكرارًا؛ وعند التعادل الأصغر.","starter":"a=list(map(int,input().split()))","hint":"استخدم Counter وترتيبًا مركبًا.","solution":"from collections import Counter\na=list(map(int,input().split()));c=Counter(a);print(min(c,key=lambda x:(-c[x],x)))","tests":[{"label":"اختبار 1","stdin":"2 3 2 4 2\n","expected_output":"2"},{"label":"اختبار 2","stdin":"5 1 5 1\n","expected_output":"1"}]},{"day":4,"diff":"beginner","title":"موجب أم سالب","instructions":"اطبع Positive أو Negative أو Zero.","starter":"n=int(input())","hint":"استخدم if وelif وelse.","solution":"n=int(input());print(\"Positive\" if n>0 else \"Negative\" if n<0 else \"Zero\")","tests":[{"label":"اختبار 1","stdin":"7\n","expected_output":"Positive"},{"label":"اختبار 2","stdin":"0\n","expected_output":"Zero"}]},{"day":4,"diff":"intermediate","title":"حذف التكرار","instructions":"احذف التكرارات مع الحفاظ على ترتيب أول ظهور.","starter":"a=list(map(int,input().split()))","hint":"استخدم set للتتبع.","solution":"a=list(map(int,input().split()));s=set();o=[]\nfor x in a:\n if x not in s:s.add(x);o.append(x)\nprint(*o)","tests":[{"label":"اختبار 1","stdin":"1 2 1 3\n","expected_output":"1 2 3"},{"label":"اختبار 2","stdin":"3 3 3\n","expected_output":"3"}]},{"day":4,"diff":"advanced","title":"دمج الفترات","instructions":"اقرأ n فترات واطبع عددها بعد دمج المتداخل.","starter":"n=int(input());a=[tuple(map(int,input().split())) for _ in range(n)]","hint":"رتب الفترات ثم ادمج المتداخل.","solution":"n=int(input());a=sorted(tuple(map(int,input().split())) for _ in range(n));m=[]\nfor s,e in a:\n if not m or s>m[-1][1]:m.append([s,e])\n else:m[-1][1]=max(m[-1][1],e)\nprint(len(m))","tests":[{"label":"اختبار 1","stdin":"3\n1 3\n2 5\n8 9\n","expected_output":"2"},{"label":"اختبار 2","stdin":"2\n1 2\n4 5\n","expected_output":"2"}]},{"day":5,"diff":"beginner","title":"أكبر ثلاثة","instructions":"اطبع أكبر ثلاثة أعداد.","starter":"a,b,c=map(int,input().split())","hint":"استخدم max.","solution":"a,b,c=map(int,input().split());print(max(a,b,c))","tests":[{"label":"اختبار 1","stdin":"4 9 2\n","expected_output":"9"},{"label":"اختبار 2","stdin":"-8 -2 -5\n","expected_output":"-2"}]},{"day":5,"diff":"intermediate","title":"المتوسط الحسابي","instructions":"اطبع المتوسط بمنزلتين عشريتين.","starter":"a=list(map(float,input().split()))","hint":"مجموع القيم على عددها.","solution":"a=list(map(float,input().split()));print(f\"{sum(a)/len(a):.2f}\")","tests":[{"label":"اختبار 1","stdin":"2 4 6\n","expected_output":"4.00"},{"label":"اختبار 2","stdin":"1 2\n","expected_output":"1.50"}]},{"day":5,"diff":"advanced","title":"أقصر مسار","instructions":"شبكة 0 و1؛ اطبع عدد خلايا أقصر مسار من أول خلية لآخر خلية. 1 حاجز، والحركة أربع اتجاهات.","starter":"from collections import deque\nr,c=map(int,input().split());g=[list(map(int,input().split())) for _ in range(r)]","hint":"استخدم BFS؛ ابدأ المسافة من 1.","solution":"from collections import deque\nr,c=map(int,input().split());g=[list(map(int,input().split())) for _ in range(r)];d=[[-1]*c for _ in range(r)]\nif g[0][0]==0:\n q=deque([(0,0)]);d[0][0]=1\n while q:\n  x,y=q.popleft()\n  for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):\n   a,b=x+dx,y+dy\n   if 0<=a<r and 0<=b<c and g[a][b]==0 and d[a][b]<0:d[a][b]=d[x][y]+1;q.append((a,b))\nprint(d[-1][-1])","tests":[{"label":"اختبار 1","stdin":"2 2\n0 0\n0 0\n","expected_output":"3"},{"label":"اختبار 2","stdin":"2 2\n0 1\n1 0\n","expected_output":"-1"}]},{"day":6,"diff":"beginner","title":"عدد الخانات","instructions":"اطبع عدد خانات عدد غير سالب.","starter":"n=input().strip()","hint":"استخدم len على النص.","solution":"print(len(input().strip()))","tests":[{"label":"اختبار 1","stdin":"345\n","expected_output":"3"},{"label":"اختبار 2","stdin":"0\n","expected_output":"1"}]},{"day":6,"diff":"intermediate","title":"تدوير القائمة","instructions":"دوّر قائمة لليمين k خطوات.","starter":"a=input().split();k=int(input())","hint":"اختصر k بباقي القسمة على الطول.","solution":"a=input().split();k=int(input())\nif a:k%=len(a);a=a[-k:]+a[:-k] if k else a\nprint(*a)","tests":[{"label":"اختبار 1","stdin":"1 2 3 4 5\n2\n","expected_output":"4 5 1 2 3"},{"label":"اختبار 2","stdin":"a b c\n4\n","expected_output":"c a b"}]},{"day":6,"diff":"advanced","title":"تحليل الأقواس","instructions":"تحقق من توازن الأقواس () [] {} وترتيبها.","starter":"s=input().strip()","hint":"استخدم stack لمطابقة آخر قوس مفتوح.","solution":"s=input().strip();st=[];p={\")\":\"(\",\"]\":\"[\",\"}\":\"{\"};ok=True\nfor ch in s:\n if ch in \"([{\":st.append(ch)\n elif ch in p:\n  if not st or st.pop()!=p[ch]:ok=False;break\nprint(\"Valid\" if ok and not st else \"Invalid\")","tests":[{"label":"اختبار 1","stdin":"{[()]}\n","expected_output":"Valid"},{"label":"اختبار 2","stdin":"([)]\n","expected_output":"Invalid"}]},{"day":7,"diff":"beginner","title":"تحويل الحرارة","instructions":"حوّل المئوية إلى فهرنهايت بمنزلتين عشريتين.","starter":"c=float(input())","hint":"F=C*9/5+32.","solution":"c=float(input());print(f\"{c*9/5+32:.2f}\")","tests":[{"label":"اختبار 1","stdin":"0\n","expected_output":"32.00"},{"label":"اختبار 2","stdin":"100\n","expected_output":"212.00"}]},{"day":7,"diff":"intermediate","title":"فيبوناتشي","instructions":"اطبع أول n أرقام من فيبوناتشي.","starter":"n=int(input())","hint":"ابدأ بـ 0 و1.","solution":"n=int(input());a,b=0,1;o=[]\nfor _ in range(n):o.append(a);a,b=b,a+b\nprint(*o)","tests":[{"label":"اختبار 1","stdin":"5\n","expected_output":"0 1 1 2 3"},{"label":"اختبار 2","stdin":"1\n","expected_output":"0"}]},{"day":7,"diff":"advanced","title":"أطول جزء بلا تكرار","instructions":"اطبع طول أطول جزء متصل بلا أحرف مكررة.","starter":"s=input().strip()","hint":"استخدم نافذة منزلقة وآخر موضع لكل حرف.","solution":"s=input().strip();last={};start=0;best=0\nfor i,ch in enumerate(s):\n if ch in last and last[ch]>=start:start=last[ch]+1\n last[ch]=i;best=max(best,i-start+1)\nprint(best)","tests":[{"label":"اختبار 1","stdin":"abcabcbb\n","expected_output":"3"},{"label":"اختبار 2","stdin":"abcdef\n","expected_output":"6"}]}]'::jsonb) as x(day smallint,diff text,title text,instructions text,starter text,hint text,solution text,tests jsonb)),
lesson_rows as (
 insert into public.programming_lessons(id,module_id,title,summary,content_md,duration_minutes,sort_order,published)
 select 'daily-challenge-'||day||'-'||diff,'cs-start-here','تحدي يومي: '||title,'تدريب يومي في أكاديمية البرمجة','تحدي برمجي يومي.',10,9000+day*3+case diff when 'beginner' then 0 when 'intermediate' then 1 else 2 end,false
 from seed on conflict(id) do update set title=excluded.title,summary=excluded.summary,content_md=excluded.content_md,updated_at=now()
 returning id
),
upserted as (
 insert into public.programming_exercises(lesson_id,title,instructions,starter_code,language,is_published,hints,solution_code,grading_mode,daily_challenge_day,daily_challenge_difficulty)
 select 'daily-challenge-'||day||'-'||diff,title,instructions,starter,'python',true,jsonb_build_array(hint),solution,'unit_tests',day,diff from seed
 on conflict(daily_challenge_day,daily_challenge_difficulty) where daily_challenge_day is not null
 do update set lesson_id=excluded.lesson_id,title=excluded.title,instructions=excluded.instructions,starter_code=excluded.starter_code,hints=excluded.hints,solution_code=excluded.solution_code,grading_mode='unit_tests',is_published=true,updated_at=now()
 returning id,daily_challenge_day,daily_challenge_difficulty
)
insert into private.programming_exercise_tests(exercise_id,test_cases)
select u.id,s.tests from upserted u join seed s on s.day=u.daily_challenge_day and s.diff=u.daily_challenge_difficulty
on conflict(exercise_id) do update set test_cases=excluded.test_cases,updated_at=now();
